// BudgetServiceHandler is an implementation of the wellspent.v1.BudgetService service.
type BudgetServiceHandler interface {
	// BudgetProfile CRUD — the stable, user-configured core of a budget
	CreateBudgetProfile(context.Context, *connect.Request[v1.CreateBudgetProfileRequest]) (*connect.Response[v1.CreateBudgetProfileResponse], error)
	ListBudgetProfiles(context.Context, *connect.Request[v1.ListBudgetProfilesRequest]) (*connect.Response[v1.ListBudgetProfilesResponse], error)
	GetBudgetProfile(context.Context, *connect.Request[v1.GetBudgetProfileRequest]) (*connect.Response[v1.GetBudgetProfileResponse], error)
	UpdateBudgetProfile(context.Context, *connect.Request[v1.UpdateBudgetProfileRequest]) (*connect.Response[v1.UpdateBudgetProfileResponse], error)
	SetBudgetCarryoverEnabled(context.Context, *connect.Request[v1.SetBudgetCarryoverEnabledRequest]) (*connect.Response[v1.SetBudgetCarryoverEnabledResponse], error)
	SetBudgetAutoUpdatePlannedAmount(context.Context, *connect.Request[v1.SetBudgetAutoUpdatePlannedAmountRequest]) (*connect.Response[v1.SetBudgetAutoUpdatePlannedAmountResponse], error)
	DeleteBudgetProfile(context.Context, *connect.Request[v1.DeleteBudgetProfileRequest]) (*connect.Response[v1.DeleteBudgetProfileResponse], error)
	// BudgetPeriod — one per cycle window; first created on profile setup, rest by the cycling job
	CreateBudgetPeriod(context.Context, *connect.Request[v1.CreateBudgetPeriodRequest]) (*connect.Response[v1.CreateBudgetPeriodResponse], error)
	ListBudgetPeriods(context.Context, *connect.Request[v1.ListBudgetPeriodsRequest]) (*connect.Response[v1.ListBudgetPeriodsResponse], error)
	GetBudgetPeriod(context.Context, *connect.Request[v1.GetBudgetPeriodRequest]) (*connect.Response[v1.GetBudgetPeriodResponse], error)
	// People — profile-scoped; shared across all periods
	AddBudgetPeople(context.Context, *connect.Request[v1.AddBudgetPeopleRequest]) (*connect.Response[v1.AddBudgetPeopleResponse], error)
	ListBudgetPeople(context.Context, *connect.Request[v1.ListBudgetPeopleRequest]) (*connect.Response[v1.ListBudgetPeopleResponse], error)
	UpdateBudgetPerson(context.Context, *connect.Request[v1.UpdateBudgetPersonRequest]) (*connect.Response[v1.UpdateBudgetPersonResponse], error)
	UpdateBudgetPersonRole(context.Context, *connect.Request[v1.UpdateBudgetPersonRoleRequest]) (*connect.Response[v1.UpdateBudgetPersonRoleResponse], error)
	UpdateMyBudgetPreferences(context.Context, *connect.Request[v1.UpdateMyBudgetPreferencesRequest]) (*connect.Response[v1.UpdateMyBudgetPreferencesResponse], error)
	UpdateMyManualMatchReviewPreference(context.Context, *connect.Request[v1.UpdateMyManualMatchReviewPreferenceRequest]) (*connect.Response[v1.UpdateMyManualMatchReviewPreferenceResponse], error)
	UpdateMyFocusedViewPreference(context.Context, *connect.Request[v1.UpdateMyFocusedViewPreferenceRequest]) (*connect.Response[v1.UpdateMyFocusedViewPreferenceResponse], error)
	RemoveBudgetPerson(context.Context, *connect.Request[v1.RemoveBudgetPersonRequest]) (*connect.Response[v1.RemoveBudgetPersonResponse], error)
	// Income sources — profile-level templates
	AddIncomeSource(context.Context, *connect.Request[v1.AddIncomeSourceRequest]) (*connect.Response[v1.AddIncomeSourceResponse], error)
	ListIncomeSources(context.Context, *connect.Request[v1.ListIncomeSourcesRequest]) (*connect.Response[v1.ListIncomeSourcesResponse], error)
	UpdateIncomeSource(context.Context, *connect.Request[v1.UpdateIncomeSourceRequest]) (*connect.Response[v1.UpdateIncomeSourceResponse], error)
	DeleteIncomeSource(context.Context, *connect.Request[v1.DeleteIncomeSourceRequest]) (*connect.Response[v1.DeleteIncomeSourceResponse], error)
	// Income entries — period-level actual amounts (pre-filled from sources, user-editable)
	ListIncomeEntries(context.Context, *connect.Request[v1.ListIncomeEntriesRequest]) (*connect.Response[v1.ListIncomeEntriesResponse], error)
	UpdateIncomeEntry(context.Context, *connect.Request[v1.UpdateIncomeEntryRequest]) (*connect.Response[v1.UpdateIncomeEntryResponse], error)
	// Savings sources — profile-level allocations
	AddSavingsSource(context.Context, *connect.Request[v1.AddSavingsSourceRequest]) (*connect.Response[v1.AddSavingsSourceResponse], error)
	ListSavingsSources(context.Context, *connect.Request[v1.ListSavingsSourcesRequest]) (*connect.Response[v1.ListSavingsSourcesResponse], error)
	UpdateSavingsSource(context.Context, *connect.Request[v1.UpdateSavingsSourceRequest]) (*connect.Response[v1.UpdateSavingsSourceResponse], error)
	DeleteSavingsSource(context.Context, *connect.Request[v1.DeleteSavingsSourceRequest]) (*connect.Response[v1.DeleteSavingsSourceResponse], error)
	// Transactions — period-scoped
	ListTransactions(context.Context, *connect.Request[v1.ListTransactionsRequest]) (*connect.Response[v1.ListTransactionsResponse], error)
	CreateTransaction(context.Context, *connect.Request[v1.CreateTransactionRequest]) (*connect.Response[v1.CreateTransactionResponse], error)
	UpdateTransaction(context.Context, *connect.Request[v1.UpdateTransactionRequest]) (*connect.Response[v1.UpdateTransactionResponse], error)
	DeleteTransaction(context.Context, *connect.Request[v1.DeleteTransactionRequest]) (*connect.Response[v1.DeleteTransactionResponse], error)
	MarkTransactionAsPaid(context.Context, *connect.Request[v1.MarkTransactionAsPaidRequest]) (*connect.Response[v1.MarkTransactionAsPaidResponse], error)
	UnmarkTransactionAsPaid(context.Context, *connect.Request[v1.UnmarkTransactionAsPaidRequest]) (*connect.Response[v1.UnmarkTransactionAsPaidResponse], error)
	SetTransactionExcluded(context.Context, *connect.Request[v1.SetTransactionExcludedRequest]) (*connect.Response[v1.SetTransactionExcludedResponse], error)
	// Converts a variable transaction into a fixed-expense installment plan:
	// excludes the transaction from totals, links it to the created plan, and
	// creates the plan with the amount split evenly across the payments.
	// Deliberately permitted on an archived period — see docs/features/installment-plans.md.
	CreateInstallmentPlan(context.Context, *connect.Request[v1.CreateInstallmentPlanRequest]) (*connect.Response[v1.CreateInstallmentPlanResponse], error)
	// Reverses CreateInstallmentPlan: deletes the plan and every payment it
	// spawned, then un-excludes and unlinks the original purchase. Refused once
	// any payment has been marked paid — that is real recorded spend.
	DeleteInstallmentPlan(context.Context, *connect.Request[v1.DeleteInstallmentPlanRequest]) (*connect.Response[v1.DeleteInstallmentPlanResponse], error)
	// Creates a FixedExpense from a variable transaction, then auto-confirms
	// the match like a regular Transaction Review.
	CreateFixedExpenseFromTransaction(context.Context, *connect.Request[v1.CreateFixedExpenseFromTransactionRequest]) (*connect.Response[v1.CreateFixedExpenseFromTransactionResponse], error)
	// Categories — user-scoped, unchanged
	ListCategories(context.Context, *connect.Request[v1.ListCategoriesRequest]) (*connect.Response[v1.ListCategoriesResponse], error)
	CreateCategory(context.Context, *connect.Request[v1.CreateCategoryRequest]) (*connect.Response[v1.CreateCategoryResponse], error)
	UpdateCategory(context.Context, *connect.Request[v1.UpdateCategoryRequest]) (*connect.Response[v1.UpdateCategoryResponse], error)
	DeleteCategory(context.Context, *connect.Request[v1.DeleteCategoryRequest]) (*connect.Response[v1.DeleteCategoryResponse], error)
	// Payment methods — profile-scoped via BudgetPerson
	ListPaymentMethods(context.Context, *connect.Request[v1.ListPaymentMethodsRequest]) (*connect.Response[v1.ListPaymentMethodsResponse], error)
	CreatePaymentMethod(context.Context, *connect.Request[v1.CreatePaymentMethodRequest]) (*connect.Response[v1.CreatePaymentMethodResponse], error)
	UpdatePaymentMethod(context.Context, *connect.Request[v1.UpdatePaymentMethodRequest]) (*connect.Response[v1.UpdatePaymentMethodResponse], error)
	DeletePaymentMethod(context.Context, *connect.Request[v1.DeletePaymentMethodRequest]) (*connect.Response[v1.DeletePaymentMethodResponse], error)
	// Expense allocations — per-person planned amounts per category; profile-scoped
	ListExpenseAllocations(context.Context, *connect.Request[v1.ListExpenseAllocationsRequest]) (*connect.Response[v1.ListExpenseAllocationsResponse], error)
	UpsertExpenseAllocation(context.Context, *connect.Request[v1.UpsertExpenseAllocationRequest]) (*connect.Response[v1.UpsertExpenseAllocationResponse], error)
	DeleteExpenseAllocation(context.Context, *connect.Request[v1.DeleteExpenseAllocationRequest]) (*connect.Response[v1.DeleteExpenseAllocationResponse], error)
	// Fixed expenses — profile-level recurring bill templates
	ListFixedExpenses(context.Context, *connect.Request[v1.ListFixedExpensesRequest]) (*connect.Response[v1.ListFixedExpensesResponse], error)
	CreateFixedExpense(context.Context, *connect.Request[v1.CreateFixedExpenseRequest]) (*connect.Response[v1.CreateFixedExpenseResponse], error)
	UpdateFixedExpense(context.Context, *connect.Request[v1.UpdateFixedExpenseRequest]) (*connect.Response[v1.UpdateFixedExpenseResponse], error)
	DeleteFixedExpense(context.Context, *connect.Request[v1.DeleteFixedExpenseRequest]) (*connect.Response[v1.DeleteFixedExpenseResponse], error)
	// Transaction review — Plaid-imported transactions that may match a fixed expense
	ListTransactionReviews(context.Context, *connect.Request[v1.ListTransactionReviewsRequest]) (*connect.Response[v1.ListTransactionReviewsResponse], error)
	ConfirmTransactionReview(context.Context, *connect.Request[v1.ConfirmTransactionReviewRequest]) (*connect.Response[v1.ConfirmTransactionReviewResponse], error)
	DismissTransactionReview(context.Context, *connect.Request[v1.DismissTransactionReviewRequest]) (*connect.Response[v1.DismissTransactionReviewResponse], error)
	MarkTransactionForReview(context.Context, *connect.Request[v1.MarkTransactionForReviewRequest]) (*connect.Response[v1.MarkTransactionForReviewResponse], error)
	// Expense summary — server-computed planned/actual/remainder totals for the
	// Expense Plan and Expense Overview tabs, so clients render instead of
	// recompute (see docs/features/expense-summary.md).
	GetExpenseSummary(context.Context, *connect.Request[v1.GetExpenseSummaryRequest]) (*connect.Response[v1.GetExpenseSummaryResponse], error)
}

